    titlerule=1pt, titlerule style={secondary},
    valign=top, drop shadow={opacity=0.3},
  },
  tealcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=primary,
    borderline west={6pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bgposter,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=1pt, titlerule style={accent},
