      {\fontsize{24}{30}\selectfont\color{textdark} Primary Platform}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══ COLUMN 1 ══
\posterbox[bluecard, title={What Is the JS Framework Benchmark?}
]{name=overview, column=1, between=row4 and row7}{
  \fontsize{26}{36}\selectfont
  \begin{itemize}[itemsep=12pt]
    \item The most widely referenced open-source benchmark for comparing JavaScript web frameworks.
    \item Measures real-world DOM operations: \textbf{creating rows, partial updates, swapping, and removal}.
    \item Runs inside a real Chrome browser with controlled CPU throttling to simulate realistic load conditions.
  \end{itemize}
}

\posterbox[tealcard, title={Timeline of Official Runs (Chrome 55 $\to$ 146)}
]{name=timeline, column=1, between=row7 and bottom}{
  \fontsize{24}{34}\selectfont
  \centering
  \vspace{8pt}
  \begin{tabular}{p{0.14\linewidth} p{0.24\linewidth} p{0.14\linewidth} p{0.36\linewidth}}
    \rowcolor{roweven}
    \textbf{Year} & \textbf{Chrome} & \textbf{Runs} & \textbf{Notes} \\
    \rowcolor{rowodd}
    2017–19 & 55 – 69 & 4 & Early era \\
    \rowcolor{roweven}
    2020 & 83 – 87 & 5 & Migrated to GitHub Pages \\
    \rowcolor{rowodd}
    2021 & 88 – 96 & 9 & Steady monthly cadence established \\
    \rowcolor{roweven}
    2022 & 97 – 108 & 13 & Includes Windows run (Chrome 104) \\
    \rowcolor{rowwarn}
    2023 & \color{warning}\textbf{109 – 120} & \color{warning}\textbf{12} & \color{warning}\textbf{Major overhaul at Chrome 118} \\
    \rowcolor{roweven}
    2024 & 121 – 131 & 12 & Includes Windows run (Chrome 121) \\
    \rowcolor{rowodd}
    2025 & 132 – 143 & 12 & Most active year; keyed-only runs \\
    \rowcolor{roweven}
    2026 & 144 – 146 & 3 & Latest runs on macOS \\
  \end{tabular}
  \vspace{16pt}

  \begin{itemize}[itemsep=10pt]
    \item \textbf{Continuous Growth}: Consistent tracking gives developers a long-term view of the JS ecosystem.
    \item \textbf{Alternating Keyed Runs}: Starting around Chrome 139, odd versions benchmark \textbf{keyed frameworks only}.
  \end{itemize}
}

% ══ COLUMN 2 ══
\posterbox[ambercard, title={Methodology Milestones}
]{name=methodology, column=2, between=row4 and row11}{
  \fontsize{26}{36}\selectfont

  \colorbox{rowwarn}{\parbox{0.92\linewidth}{
    \centering\vspace{6pt}
    \textbf{\color{warning}Cross-version comparisons are dangerous without understanding methodology changes.}\vspace{6pt}
  }}
  \vspace{16pt}

  \begin{itemize}[itemsep=14pt]
    \item \textbf{Chrome 118 (2023): Weighted Geometric Mean}\\
    Switched overall score from arithmetic to weighted geometric mean. This is the single most important reason cross-version comparisons break down.
    \item \textbf{Chrome 118: CPU Throttling Adjustment}\\
    Throttling factors recalibrated for more realistic load simulation across modern devices.
    \item \textbf{Chrome 118+: Measurement Fine-Tuning}\\
    Ongoing refinements to timing and driver instrumentation to improve accuracy.
    \item \textbf{Chrome 139+ (2025): Keyed-Only Alternation}\\
    Odd Chrome versions often benchmark keyed frameworks only.
  \end{itemize}
}

\posterbox[bluecard, title={Platform Coverage}
]{name=coverage, column=2, between=row11 and row15}{
  \fontsize{26}{36}\selectfont
  \begin{itemize}[itemsep=12pt]
    \item Over \textbf{95\%} of official runs executed on \textbf{macOS (OSX)}.
    \item Only \textbf{two} Windows-specific runs exist in 8 years:
    \begin{itemize}
        \item Chrome 104 (2022)
        \item Chrome 121 (2024)
    \end{itemize}
    \item The benchmark primarily reflects \textbf{macOS + Chrome} performance characteristics.
  \end{itemize}
}

\posterbox[tealcard, title={Key Takeaways for Developers}
]{name=takeaways, column=2, between=row15 and bottom}{
  \fontsize{26}{36}\selectfont
  \begin{itemize}[itemsep=16pt]
    \item \textbf{Always compare within the same Chrome version.}\\
    Methodology and throttling differ across releases.
    \item \textbf{Consult the latest run (Chrome 146).}\\
    Provides the most up-to-date framework standings.
    \item \textbf{Understand keyed vs non-keyed modes.}\\
    Odd-numbered Chrome runs benchmark keyed only.
    \item \textbf{Weighted geometric mean (Chrome 118+)}\\
    Gives a more balanced, reliable overall score.
  \end{itemize}
}

\end{tcbposter}
\end{document}

